bool RemoveWithTwoChildren(TNode *tree, TNode **p) {
    if (!p || !*p)    
        return false;

    if ((*p)->left && (*p)->right) { // 如果节点有左右子节点
        TNode* successor = (*p)->right; // 取右子节点为后继节点
