class Solution {
public:
    int getBiggestThree(vector<vector<int>>& grid) {
        sort(grid.rbegin(), grid.rend());
        int ans = 0;    
        int cur = grid[0][0] + grid[0][1];        
        ans = max(ans, cur);    
        int prev = cur;
        int cnt = 1;    
