class Solution:
    def isIsomorphic(self, s: str, t: str) -> bool:
        if len(s) != len(t):
            return False
        s_map = {}
        for i in range(len(s)):
            if s[i] in s_map.keys():
                if t[i] == s_map[s[i]]:
                    continue
                else:
                    return False
            else:
                if t[i] in s_map.values():
                    return False
                else:
                    s_map[s[i]] = t[i]
        return True
