既然你希望程序中自行車（ bicycles ）和車輛（ vehicles ）的數量相等，你可以寫一個類似這樣的函數來進行檢查並調整：

```python
from collections import Counter

def check_and_balance_traffic(vehicles_list, bicycles_list):
    """ 檢查並平衡自行車和車輛的數量 """
    # 計算每種交通工具的數量
    vehicle_counts = Counter(vehicles_list)
    bicycle_counts = Counter(bicycles_list)

    # 相應調整以達到平衡 （例如，刪除多餘的部分）
    for vehicle_type in vehicle_counts:
        for bicycle_type in bicycle_counts:
            # Ensuring equal quantity by removing excess
            excess = abs(vehicle_counts[vehicle_type] - bicycle_counts[bicycle_type])
            if excess > 0:
                if vehicle_counts[vehicle_type] > bicycle_counts[bicycle_type]:
                    vehicles_list.remove(list(vehicle_counts)[0])  # Remove vehicle first
                else:
                    bicycles_list.remove(bicycle_counts[bicycle_type] - excess)

    return vehicles_list, bicycles_list

# 使用

traffic_data = ["vehicle", "bike", "vehicle", "vehicle", "bike", "bike"]
